cards.solution:
const halaman = { beranda: true, promo: false, artikel: true };
const muat = (nama) => new Promise((res, rej) =>
  setTimeout(() => (halaman[nama] ? res(nama) : rej(new Error(`${nama} gagal`))), 100)
);
async function muatSemua(daftar) {
  const hasil = await Promise.allSettled(daftar.map(muat));
  const berhasil = hasil.filter((h) => h.status === "fulfilled").length;
  console.log("Berhasil:", berhasil);
  console.log("Gagal:", hasil.length - berhasil);
}
await muatSemua(["beranda", "promo", "artikel"]);
